const icon = {home:"⌂", learn:"▤", interview:"◉", build:"⌘", play:"▧", check:"✓", spark:"✦", clock:"◷", chart:"⌁", layers:"▦", database:"▤", cache:"◈", queue:"⇢", worker:"⚙", client:"◉", cdn:"◌", balancer:"⇄", storage:"▣"};
const lessons = [
  {stage:"01 · Start here", level:"Foundations", title:"What happens when you open a website?", time:"8 min", lede:"A system is a set of parts that cooperate to deliver a result. Start with the simplest useful picture: a client asks, a server answers.", sections:[["The request journey","You type a URL. The browser finds an address, opens a connection, sends an HTTP request, and waits. A server reads the request, fetches or computes data, and sends a response. The browser turns that response into a page."],["Why draw the path?","A request path gives us a map. When a page feels slow, we can ask where time is spent: the network, application code, a database query, or a downstream service."],["A useful first diagram","Client → API server → database. Each arrow is a request or response. Each box owns a responsibility. Keep the first version small; complexity earns its place when a requirement demands it."]], takeaway:"A system design is a model of how requests and data move, plus the choices that make the system meet its goals.", question:"What is the most useful first step when a user reports that a page is slow?", choices:["Add a cache immediately","Trace the request path and measure where time is spent","Rewrite the database","Add more servers"], answer:1, explanation:"Measure the path first. The slow part might be the network, an inefficient query, overloaded compute, or an external dependency."},
  {stage:"01 · Start here", level:"Foundations", title:"Turn a vague prompt into requirements", time:"10 min", lede:"Interview prompts are intentionally incomplete. Your first job is to make the problem small enough to reason about.", sections:[["Functional requirements","Write down what people can do: create a link, open a link, or see click analytics. These become the core user journeys and APIs."],["Quality requirements","Ask how fast, how available, how much data, and for how many users. Numbers make architectural tradeoffs discussable."],["Scope the first version","Clarify what can wait. If link analytics are optional, keep them out of the redirect path and design them as a separate flow."]], takeaway:"Ask focused questions, state assumptions, and repeat the scope back before drawing boxes.", question:"Which question most directly clarifies the scale of a design?", choices:["What color should the button be?","How many requests per second should the system handle?","Which editor wrote the prompt?","What is the project codename?"], answer:1, explanation:"Request volume drives capacity and data decisions. The UI color does not change the system architecture."},
  {stage:"01 · Start here", level:"Foundations", title:"Estimate before you architect", time:"12 min", lede:"A rough order-of-magnitude estimate can rule out designs that look elegant but cannot carry the load.", sections:[["Start with users and actions","Suppose one million people use a service monthly and each makes ten requests a day. That is about ten million requests per day."],["Convert to average QPS","10,000,000 ÷ 86,400 ≈ 116 requests per second on average. Real traffic is bursty, so peak load might be several times higher."],["Estimate storage","If each record is 1 KB and you create a million records per day, raw growth is about 1 GB per day before indexes, replicas, and backups."]], takeaway:"Write each assumption beside the result. A rough estimate with visible assumptions is more useful than a precise-looking guess.", question:"10 million requests arrive evenly over one day. About how many requests per second is that?", choices:["About 12","About 116","About 1,160","About 10,000"], answer:1, explanation:"10,000,000 divided by 86,400 seconds is roughly 116 requests per second."},
  {stage:"02 · Core building blocks", level:"Core", title:"Design a small API", time:"11 min", lede:"An API is a contract between callers and your service. Good boundaries make systems easier to change and operate.", sections:[["Start with resources","For a URL shortener, a link is a resource. A create request might accept a long URL and return a short code. A redirect request resolves that code."],["Keep contracts explicit","Document methods, paths, request fields, response codes, and validation. Think about duplicate requests and what should happen when a record does not exist."],["Idempotency","A retry should not accidentally create multiple payments or orders. An idempotency key lets the service recognize a repeated request and return the original result."]], takeaway:"Design the API around the user journey and the data owner. Make retries safe where duplicate work would be harmful.", question:"What does an idempotency key help a service do?", choices:["Encrypt every response","Recognize a retry as the same logical request","Increase database storage","Route traffic to a CDN"], answer:1, explanation:"The key identifies a logical operation so a repeated request can reuse its earlier result instead of repeating the side effect."},
  {stage:"02 · Core building blocks", level:"Core", title:"Choose a data model", time:"13 min", lede:"Pick the shape of the data from the access patterns you need to support, not from fashion.", sections:[["Model the reads and writes","List the most common queries first. A service that looks up a short code needs a fast key-to-destination mapping. A reporting feature may need a different read model."],["Relational or key-value?","Relational databases support transactions, constraints, and flexible queries. Key-value stores can make simple lookups fast at large scale. Many products use both for different jobs."],["Indexes cost something","An index speeds selected reads but consumes storage and adds work to writes. Add it for a measured query pattern, then check that it is used."]], takeaway:"Write down the queries before selecting a database. Data ownership and access patterns guide the choice.", question:"What is the main cost of adding an index?", choices:["Writes and storage become more expensive","Network requests stop working","The database loses transactions","The API has to use a queue"], answer:0, explanation:"Indexes use disk and must be updated as rows change, so they add storage and write overhead."},
  {stage:"02 · Core building blocks", level:"Core", title:"Cache hot reads", time:"12 min", lede:"A cache stores frequently used data closer to the caller so repeated reads avoid expensive work.", sections:[["Cache-aside","The application checks the cache first. On a miss it reads the source of truth, returns the result, and populates the cache."],["Freshness is a product decision","A cached value can be stale. Choose a time-to-live based on how much staleness users can tolerate. For critical values, invalidate or update deliberately."],["Watch for stampedes","If a popular key expires, many requests can hit the database at once. Jittered expiration, request coalescing, and stale-while-revalidate can reduce the surge."]], takeaway:"Caching improves repeated reads, but adds a freshness policy and another failure mode.", question:"In cache-aside, where does an application read after a cache miss?", choices:["The source of truth","The CDN only","A random cache key","The client browser history"], answer:0, explanation:"On a miss, the application reads the authoritative data store and can then populate the cache."},
  {stage:"03 · Scale & distribute", level:"Scaling", title:"Scale stateless services", time:"14 min", lede:"When one application server is not enough, more instances can share traffic—if requests do not depend on hidden local state.", sections:[["Vertical and horizontal scaling","A larger server is simple to reason about but has a ceiling. Multiple smaller instances provide more capacity and can tolerate an instance failure."],["Load balancing","A load balancer routes requests across healthy instances. Health checks keep known-bad instances out of rotation."],["Keep session state outside","If a server stores a user session only in memory, a later request routed elsewhere may lose it. Use a shared session store or stateless signed tokens where appropriate."]], takeaway:"Horizontal scaling works best when any healthy instance can handle any request.", question:"What makes a web service easier to scale horizontally?", choices:["Every instance has unique local session data","Instances are stateless or use shared state","Only one instance can write","Requests never time out"], answer:1, explanation:"A request can go to any healthy instance when important state is shared or carried safely in the request."},
  {stage:"03 · Scale & distribute", level:"Scaling", title:"Move slow work to a queue", time:"13 min", lede:"Queues separate a fast user-facing request from work that can finish later.", sections:[["Producer, queue, consumer","The API records a job and publishes a message. A worker consumes it and performs the slower task, such as sending an email or generating a report."],["At-least-once delivery","Many queues may deliver a message again after a timeout. Consumers should make repeated processing safe with idempotency or deduplication."],["Backpressure and dead letters","Monitor queue age and depth. If workers cannot keep up, reject or slow producers, scale consumers carefully, and route repeatedly failing messages to a dead-letter queue."]], takeaway:"Queues absorb bursts, but they do not create infinite capacity. Monitor lag and make consumers safe to retry.", question:"Why should a queue consumer often be idempotent?", choices:["Messages can be delivered more than once","Queues do not preserve data","It makes the database faster","It eliminates monitoring"], answer:0, explanation:"Retries and redelivery can repeat a message. Idempotent handling avoids duplicating the resulting side effect."},
  {stage:"03 · Scale & distribute", level:"Scaling", title:"Partition large data", time:"15 min", lede:"Partitioning divides a large dataset across machines. The partition key determines where each record lives.", sections:[["Choose a key with care","A good key spreads traffic while keeping common lookups targeted. A poor key creates hot partitions or forces expensive scatter-gather queries."],["Range and hash partitioning","Range partitioning keeps nearby values together, which helps range scans but can create hot ends. Hash partitioning spreads keys evenly but makes range queries harder."],["Plan for change","Adding partitions, changing a key, or moving tenants can be operationally difficult. Know how rebalancing works before the system reaches its limit."]], takeaway:"Partitioning trades simpler single-node operations for scale and distribution complexity.", question:"What is a common risk of choosing a monotonically increasing ID as a range partition key?", choices:["Every read becomes strongly consistent","New writes can pile onto the newest partition","It prevents backups","It removes all indexes"], answer:1, explanation:"Sequential IDs concentrate recent writes in the newest range, which can become a hot partition."},
  {stage:"04 · Reliable systems", level:"Advanced", title:"Design for failure", time:"15 min", lede:"Distributed systems fail in partial ways: one dependency can be slow while the rest of the system is healthy.", sections:[["Timeouts and deadlines","Every network call needs a bounded wait. Propagate a deadline so nested services do not keep working after the caller has given up."],["Retries with backoff","Retry transient failures with exponential backoff and jitter. Bound attempts so retries do not amplify an outage."],["Circuit breakers and fallbacks","A circuit breaker temporarily stops calls to an unhealthy dependency. A fallback may serve stale or reduced functionality if the product allows it."]], takeaway:"Reliability comes from bounded work, controlled retries, graceful degradation, and clear failure signals.", question:"Why add jitter to exponential backoff?", choices:["To make retries synchronize","To spread retries so clients do not all retry at once","To disable timeouts","To reduce database consistency"], answer:1, explanation:"Randomized delay spreads retries over time and avoids synchronized retry bursts."},
  {stage:"04 · Reliable systems", level:"Advanced", title:"Consistency and replication", time:"16 min", lede:"Replication improves availability and read capacity, but copies can disagree temporarily.", sections:[["Primary and replicas","Writes may go to one primary and propagate to read replicas. A read immediately after a write can hit a replica that has not caught up."],["Strong and eventual consistency","Strong consistency gives callers a more current view at a coordination cost. Eventual consistency permits temporary differences that converge later."],["Choose per workflow","A profile photo can often tolerate a short delay. A bank transfer ledger generally needs stronger guarantees and careful transactional boundaries."]], takeaway:"State what users must observe, then choose consistency guarantees that match the workflow.", question:"Which feature usually tolerates eventual consistency best?", choices:["A balance after a transfer","A profile photo thumbnail","A unique username reservation","An inventory decrement at checkout"], answer:1, explanation:"A brief delay before a new photo appears is generally less harmful than stale financial or inventory state."},
  {stage:"04 · Reliable systems", level:"Advanced", title:"Observe the system in production", time:"12 min", lede:"If you cannot see how a system behaves, you cannot reliably improve it.", sections:[["Metrics","Track request rate, error rate, latency percentiles, and saturation. Averages hide slow tail requests, so look at p95 or p99 latency too."],["Logs and traces","Logs explain individual events. Distributed traces connect a request across service boundaries and show where time is spent."],["SLOs and alerts","Set a user-facing reliability target, such as a percentage of requests below a latency limit. Alert on meaningful user impact, not every noisy metric."]], takeaway:"Instrument the user journey and use service objectives to guide capacity and reliability work.", question:"Why monitor p95 latency instead of only average latency?", choices:["It highlights slower requests affecting a meaningful share of users","It removes the need for logs","It measures database size","It guarantees uptime"], answer:0, explanation:"Averages can hide a long tail. p95 shows the latency below which 95% of requests finish."},
];

